entries[234128] = { ["name"] = "Neighborhood Renaming Permit", ["text"] = "Binds when picked up\n\"Used to rename a neighborhood that you manage. Purchased from your neighborhood steward.\"" }
entries[234185] = { ["name"] = "Dr. Scrapheal", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+18 Intellect\nEquip: Your healing spells and abilities have a chance to summon Dr. Scrapheal to heal your target additionally for 620 .\n\nWhen a nearby ally's health falls below 35%, Dr. Scrapheal springs into action, delivering instant care to heal them for 2418 . This effect can only activate once every 1 min.\nSell Price:" }
entries[234188] = { ["name"] = "Slot Chits", ["text"] = "Quest Item\n\"Redeemable at any participating Gallagio establishment.\"" }
entries[234197] = { ["name"] = "Gilded Screwdriver", ["text"] = "\"The gold is peeling off.\"\nSell Price:" }
entries[234203] = { ["name"] = "Clay-Speckled Metal Slug", ["text"] = "\"It's got a nice weight to it.\"\nSell Price:" }
entries[234204] = { ["name"] = "Depleted Battery", ["text"] = "\"It's corroded at the ends.\"\nSell Price:" }
entries[234205] = { ["name"] = "Bent Lever", ["text"] = "\"Gallywix's face is engraved on the handle at the end.\"\nSell Price:" }
entries[234212] = { ["name"] = "\"Beaten by the House\"", ["text"] = "\"Tales of punishment of those who thought they could win at The Gallagio.\"\nSell Price:" }
entries[234217] = { ["name"] = "Funhouse Lens", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+18 [Agility or Strength or Intellect]\nUse: Look through the lens and randomly scale up or down, gaining 129 Critical Strike or Haste for 15 sec. (1 Min, 30 Sec Cooldown)\n\"Tall today, tiny tomorrow.\"\nSell Price:" }
entries[234218] = { ["name"] = "Goo-blin Grenade", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+18 Intellect\nUse: Coat the enemy in a layer of unstable slime, dealing 3364 Nature damage over 10 sec. If the target dies while slimed, it releases corrosive goo that deals 1612 Nature damage, split between nearby enemies. (1 Min, 30 Sec Cooldown)\nSell Price:" }
