entries[234273] = { ["name"] = "A Dimmed Crystal", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires level 80 to 80 ( 80)\n\"This cold and dark crystal comes to life with your touch. A faded deep blue glow emanates within it. You can hear a faint song within your mind.\"" }
entries[234274] = { ["name"] = "Schematic: 22H Slicks", ["text"] = "Binds when picked up\nUse: Teaches you how to make 22H Slicks.\nRequires Khaz Algar Engineering (25)\nRequires Khaz Algar Engineering and Renown Rank 5 with the Cartels of Undermine.\nSell Price:" }
entries[234281] = { ["name"] = "Undermine Cartel Work", ["text"] = "\"Your chosen cartel will assign world quests and other activities to your Warband this week.\"" }
entries[234282] = { ["name"] = "Decorative Yard Flamingo", ["text"] = "Use: Place a Decorative Yard Flamingo to create a relaxing atmosphere anywhere you go. (5 Min Cooldown)\n\"Add a bit of flamingo decor flare wherever you go.\"\nSell Price:" }
entries[234287] = { ["name"] = "Radiant Focus", ["text"] = "Use: Attempt to interpret the sacred energy within.\n\"A faint mote of light glimmers from this radiant remnant.\"\nSell Price:" }
entries[234326] = { ["name"] = "Core Recycling Unit", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+18 [Agility or Strength]\nEquip: Add an energy core to the container for every enemy slain, up to a maximum of 20.\nUse: Consume all stored energy cores to send a surge of restorative energy through you, instantly healing you for 5485 , with an additional 235 healing over 10 seconds for each core consumed. (1 Min, 30 Sec Cooldown)\nSell Price:" }
entries[234327] = { ["name"] = "Turbulent Fragment", ["text"] = "Binds when picked up\nUse: Combine 3 Turbulent Fragments to create a Turbulent Runekey.\n\"Even shattered, the stone vibrates with a restless energy. Tossing and turning, the stone rattles around in your bags constantly.\"\nSell Price:" }
entries[234328] = { ["name"] = "Torrential Fragment", ["text"] = "Binds when picked up\nUse: Combine 7 Torrential Fragments to create a Torrential Runekey.\n\"While seemingly lifeless, peering at the stone fills your mind with images of vast oceans. Seas with unfathomable depths. A wave of fear washes over you as the sheer volume of it all overwhelms you.\"\nSell Price:" }
