entries[234716] = { ["name"] = "Nightfall Skyreaver's Reins", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses an Nightfall Skyreaver. This mount changes depending on your Riding skill and location.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Descending on their prey in the dead of night, the cries of these skyreavers once instilled terror in all the children of Draenor.\"\nVendor:\nKronnus\nZone:\nWarspear\nCost:\n5000\n\nVendor:\nTempra\nZone:\nStormshield\nCost:\n5000" }
entries[234717] = { ["name"] = "Blastmaster3000", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+18 [Agility or Intellect]\nUse: Launch a random number of deadly grenades at your enemies, each dealing ( 1343 * 1 ) Fire damage split between nearby targets caught in the blast. (1 Min Cooldown)\n\"Could be single, maybe double, or if you're lucky, TRIPLE explosions!\"\nSell Price:" }
entries[234718] = { ["name"] = "Ancient Runic Hilt", ["text"] = "\"The visage of a female figure has been engraved into the rune-scripted hilt.\"\nSell Price:" }
entries[234719] = { ["name"] = "Storm-Etched Vambrace", ["text"] = "\"The depiction of a stormy mountain peak has been engraved into the bracer.\"\nSell Price:" }
entries[234720] = { ["name"] = "Memoric Residue", ["text"] = "\"The golden dust-like substance appear to be both spectral and physical in nature.\"\nSell Price:" }
entries[234721] = { ["name"] = "Ur'zul Fleshripper Bridle", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses your Ur'zul Fleshripper.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"This terrifying ur'zul incorporates its latest victims into itself, creating a nearly unstoppable monster. Good thing you are treating it well, or you might be its next treat.\"\nVendor:\nAridormi\nZone:\nDalaran\nCost:\n5000" }
entries[234722] = { ["name"] = "Carved Stone Fragment", ["text"] = "\"The stone fragment is all that remains of an ancient stone construct.\"\nSell Price:" }
entries[234723] = { ["name"] = "Hollow Sigil", ["text"] = "\"Faded etchings surround a now-empty gem setting in the center of the sigil.\"\nSell Price:" }
entries[234724] = { ["name"] = "Topsy Turvy Clown's Cleaver", ["text"] = "Cosmetic\nBinds to Warband\nOne-Hand Axe\n1 Damage Speed 1.80\n(0.6 damage per second)\n\"With a turn of phrase or wrist, someone might just find themselves splitting up.\"\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[234725] = { ["name"] = "Topsy Turvy Jester's Cleaver", ["text"] = "Cosmetic\nBinds to Warband\nOne-Hand Axe\n1 Damage Speed 1.80\n(0.6 damage per second)\n\"Wielding this axe while telling a joke guarantees a reaction.\"\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[234726] = { ["name"] = "Topsy Turvy Joker's Cleaver", ["text"] = "Cosmetic\nBinds to Warband\nOne-Hand Axe\n1 Damage Speed 1.80\n(0.6 damage per second)\n\"Wielding this axe while telling a joke guarantees a reaction.\"\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[234727] = { ["name"] = "Topsy Turvy Fool's Cleaver", ["text"] = "Cosmetic\nBinds to Warband\nOne-Hand\n\"Properly weighted for juggling, but the eyes seem to watch your performance.\"\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[234729] = { ["name"] = "Cache of Undermine Treasures", ["text"] = "Binds when picked up\n\"Rewards a piece of equipment for your Loot Specialization.\"\n<Right Click to Open>" }
entries[234730] = { ["name"] = "Broodling of Sinestra", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"After the fall of the Bastion of Twilight, a few scattered twilight whelps escaped Vexiona's sway. Some of these whelps have allied with mortals and are willing to bear them as riders.\"\nVendor:\nKiatke\nZone:\nStormwind City\nZone:\nOrgrimmar\nCost:\n5000" }
entries[234731] = { ["name"] = "Cache of Undermine Treasures", ["text"] = "Heroic\nBinds when picked up\n\"Rewards a piece of equipment for your Loot Specialization.\"\n<Right Click to Open>" }
entries[234732] = { ["name"] = "Bloodied Medallion", ["text"] = "\"Prized among the Bloodwake, these medallions are worn only by those who've won their first hundred bloody victories.\"\nSell Price:" }
entries[234733] = { ["name"] = "Bloodwake Ritual Bowl", ["text"] = "\"The shallow ritual bowl is stained with blood-red... pigment, probably.\"\nSell Price:" }
entries[234734] = { ["name"] = "Inscribed Drinking Horn", ["text"] = "\"The depiction of a vrykul vessel assaulted by winged creatures from the sea has been engraved onto the ivory.\"\nSell Price:" }
entries[234735] = { ["name"] = "Battered Vrykul Lantern", ["text"] = "\"Even the bravest of vrykul refuse to embark on the open sea without their lantern. They believe it wards off the darkness beneath the waves.\"\nSell Price:" }
entries[234736] = { ["name"] = "Tar-Sealed Scroll", ["text"] = "\"The seachart within depicts the Bloodwake ship routes and the many islands they lay siege to. Strangely, the Siren Isle is marked with a warning indicator.\"\nSell Price:" }
entries[234740] = { ["name"] = "Copper-Maned Quilen Reins", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses an Copper-Maned Quilen. This mount changes depending on your Riding skill and location.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Raised in the stables of the Iron Qon, these mounts are ardently steadfast, never leaving their posts even when they sensed the demise of their masters.\"\nVendor:\nMistweaver Xia\nZone:\nTimeless Isle\nCost:\n5000" }
entries[234741] = { ["name"] = "Miscellaneous Mechanica", ["text"] = "Binds to Warband\n\"Spare parts, in good enough shape to be used for a variety of machinery.\"" }
entries[234743] = { ["name"] = "Steamwheedle's Trove", ["text"] = "Binds to Warband\nUnique\n\"Contains resonance crystals and a small amount of gold for those who have proven themselves to the Steamwheedle Cartel.\"\n<Right Click to Open>" }
entries[234744] = { ["name"] = "Blackwater's Trove", ["text"] = "Binds to Warband\nUnique\n\"Contains resonance crystals and a small amount of gold for those who have proven themselves to the Blackwater Cartel.\"\n<Right Click to Open>" }
