entries[234750] = { ["name"] = "Myrmidon's Osminium Bracer", ["text"] = "\"The faded sigil of Nazjatar is engraved on the surface, surrounded by the words \"For her Glory\".\"\nSell Price:" }
entries[234751] = { ["name"] = "Pearl-Adorned Tailband", ["text"] = "\"Arcane runes flicker across the prismatic surface of the pearl.\"\nSell Price:" }
entries[234752] = { ["name"] = "Coral-Pocked Scrying Stone", ["text"] = "\"The stone may be inert but the magic that once imbued it lingers faintly. It appears to have been used recently.\"\nSell Price:" }
entries[234753] = { ["name"] = "Cracked Divining Scepter", ["text"] = "\"Before it was damaged, this scepter appears to have been attuned specifically to the crystals and ore of the Siren Isle.\"\nSell Price:" }
entries[234754] = { ["name"] = "Bloodied Siren Pendant", ["text"] = "\"The bloodied, ornate face of the pendant have been shattered by something heavy and sharp.\"\nSell Price:" }
