entries[235359] = { ["name"] = "Ratfang Toxin", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+18 [Agility or Strength or Intellect]\nEquip: Your harmful spells and abilities apply Ratfang Toxin to your target, stacking up to 5 times.\nUse: Release all toxin stacks to deal ( 2943 * 1 ) Nature damage, plus ( 336 * 1 ) per stack over 5 sec. (1 Min, 30 Sec Cooldown)\nSell Price:" }
entries[235363] = { ["name"] = "Suspicious Energy Drink", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+18 [Agility or Strength or Intellect]\nEquip: When you use harmful spells or abilities, there is a chance you also take a sip of the energy drink, increasing your Mastery by 61 for 10 sec. Gain an additional 9 Mastery if you are below 35% health.\n\"A death-defying concoction made with Mama's secret recipe to numb your sense of self-preservation.\"\nSell Price:" }
