entries[235388] = { ["name"] = "Paint: Redlining Red", ["text"] = "Binds when picked up\nUnique\nUse: Purchase this paint to permanently unlock this color palette for your G-99 Breakneck.\nRequires Exalted reputation with the Bilgewater Cartel in Undermine.\n\"Red is, of course, the fastest color.\"" }
