entries[235499] = { ["name"] = "Reshii Wraps", ["text"] = "Binds when picked up\nBack\n7 Armor\n+7 [Agility or Strength or Intellect]\n+10 Stamina\n\nFiber Socket\nEquip: [The wraps attune to your specialization granting you Ethereal Reconstitution :\n\nYour helpful spells and abilities have a chance to gather dormant energy to heal an injured ally for 1899 . Overhealing from this effect grants an absorb shield for 20 sec. ][The wraps attune to your specialization granting you Ethereal Protection :\n\nYour spells and abilities have a high chance to coalesce the energy around you, granting you a shield that reduces damage taken by 20% up to 2954 total damage.\n\nUpon falling below 40% health, gain this effect at 500% effectiveness. This effect may only occur once every 6 min. ][The wraps attune to your specialization granting you Ethereal Reaping :\n\nYour harmful spells and abilities have a chance to focus latent energies around you to inflict 1477 Arcane damage split between your target and nearby enemies. Enemies below 35% health take 20% additional damage. ]\nSell Price:" }
entries[235500] = { ["name"] = "Tranquilizing Dart", ["text"] = "Quest Item\nUse: Shoots a Tranquilizer Dart at your target, causing them to fall into a deep and blissful slumber.\n\"Tranquilizes anything it's thrown at by temporarily disrupting their spiritual web. Non-invasive and pain-free. Apparently a common prank to pull on unsuspecting friends.\"" }
