entries[235532] = { ["name"] = "Experimental Goblin-FUEL Supplement", ["text"] = "Binds to Warband\nUse: Reduces maximum health by 50% and provides a random combat benefit.\n\nOnly usable in Undermine. Enemies drop additional Market Research for the caster while active. (5 Min Cooldown)\n\"Expiration Date: 'What are you, a quitter?'\"" }
entries[235533] = { ["name"] = "Prototype Auto-Advertiser", ["text"] = "Binds to Warband\nUse: Place the auto-advertiser, causing all nearby creatures to become extremely annoyed and inflict 50% increased damage to you for 3 min.\n\nOnly usable in Undermine. Enemies drop additional Market Research for the caster while active. (5 Min Cooldown)\n3 Charges\nRequires Friendly reputation with the Darkfuse Cartel in Undermine.\n\"Comes preloaded with a minimal suite of ads. Get YOUR personal brand recognized in style!\"" }
entries[235535] = { ["name"] = "Discretely-Packaged Invention", ["text"] = "Binds to Warband\n\"Ain't no solution like a Darkfuse Solution. Wait, that's a pretty good slogan. Write that down!\"" }
