entries[235555] = { ["name"] = "Lively Darkmoon Charger", ["text"] = "Binds to Warband\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Lively Darkmoon Charger.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Draped in tattered circus banners, this eerie mount is a perfect blend of shadow and spectacle.\"\nTrading Post" }
entries[235556] = { ["name"] = "Violet Darkmoon Charger", ["text"] = "Binds to Warband\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Violet Darkmoon Charger.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"This steed carries the mystery and magic of the Darkmoon Faire on its back.\"\nTrading Post" }
