entries[235626] = { ["name"] = "Keys to the Big G", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses Gallytron.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Doesn't actually seem like anything too special under the hood, but just wait until those goblins next door see you pull up for the next pool party.\"\nDrop:\nChrome King Gallywix\nZone:\nLiberation of Undermine (Mythic)" }
entries[235627] = { ["name"] = "Scribbles' Favorite Candies", ["text"] = "Binds when picked up\nUnique\n\"Ensures Scribbles is always ready to reset your Profession Specialization.\"" }
entries[235628] = { ["name"] = "Delver's Bounty", ["text"] = "Requires level 70 to 80 ( 80)\n\"Chance to receive a Delver's Bounty from a Bountiful delve's Heavy Trunk. Using this rare map will lead you to a Hidden Trove containing powerful equipment, bonus currencies, and a new or upgraded curio. Obtainable once per week per character.\"" }
entries[235629] = { ["name"] = "Renzik's Journal", ["text"] = "Binds when picked up\n\"The fake leather binding has started to crumble around the edges.\"\n<Right Click to Read>" }
